import unittest


def simplify(x, n):
    a, b = x.split("/")
    c, d = n.split("/")
    numerator = int(a) * int(c)
    denom = int(b) * int(d)
    if (numerator / denom == int(numerator / denom)):
        return True
    return False


class TestSimplify(unittest.TestCase):

    def test_product_is_whole_number(self):
        self.assertTrue(simplify("1/5", "5/1"))

    def test_product_is_not_whole_number(self):
        self.assertFalse(simplify("1/2", "1/2"))

    def test_two_whole_numbers(self):
        self.assertTrue(simplify("2/1", "3/1"))

    def test_reciprocal_fractions(self):
        self.assertTrue(simplify("7/2", "2/7"))

    def test_fraction_times_whole(self):
        self.assertTrue(simplify("1/2", "4/1"))

    def test_non_whole_result(self):
        self.assertFalse(simplify("1/3", "2/1"))

    def test_zero_numerator(self):
        self.assertTrue(simplify("0/1", "5/2"))

    def test_large_numbers(self):
        self.assertTrue(simplify("100/3", "3/100"))

    def test_result_is_fraction(self):
        self.assertFalse(simplify("2/3", "3/4"))

    def test_multiplied_to_three(self):
        self.assertTrue(simplify("3/2", "2/1"))


if __name__ == "__main__":
